const Work=(()=>{
 const catalog=WorkCatalog.modules;
 const model=WorkModel.create(localStorage,()=>({committee:A0.activeCommittee(),phone:A0.phone(),member:A0.membership()?.member}));
 const $=s=>document.querySelector(s);let moduleId='A4',tab='',selected='',query='',status='',taskScope='all',sampleValues=null;
 const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const c=()=>A0.activeCommittee();const person=()=>A0.membership()?.member;
 const memberName=id=>c().members.find(m=>m.id===id)?.name||'未分配';
 const get=id=>model.read().records.find(r=>r.id===id);
 const mod=()=>catalog.find(x=>x.id===moduleId);
 const definition=()=>model.def(moduleId,tab);
 const records=()=>model.read().records.filter(r=>r.module===moduleId&&(!mod().tabs||r.type===tab));
 const date=()=>new Date().toISOString().slice(0,10);
 const future=(days=30)=>new Date(Date.now()+days*86400000).toISOString().slice(0,10);
 function navigate(id,type='',record=''){moduleId=id;tab=type||catalog.find(m=>m.id===id)?.tabs?.[0]||'';selected=record;query='';status='';page='work';render()}
 function openRecord(id){const r=get(id);if(r)navigate(r.module,r.type,r.id);else toast('记录不存在或不属于当前业委会')}
 function error(e){const el=$('#work-error');if(el)el.textContent=e.message||e;else toast(e.message||e)}
 function safe(fn){try{fn()}catch(e){error(e)}}
 const errorHTML=()=>'<p id="work-error" class="a0-error" role="alert"></p>';
 function directory(){return `<div class="workspace work-page"><div class="page-head"><h1>小区事务</h1><span class="pill">业委会 Web 端</span></div><label class="search">${icon('search')}<input id="work-module-search" placeholder="查找模块或事项" aria-label="查找模块或事项"></label><div class="business-grid" id="work-directory">${['会议与决定','物业与资金','公示与文书','组织与小区'].map(g=>`<section class="business-group"><h2>${g}</h2><div class="business-items">${catalog.filter(m=>m.group===g).map(m=>`<button data-module="${m.id}">${m.name}</button>`).join('')}</div></section>`).join('')}</div><details class="work-deferred"><summary>文档中的二期范围</summary><p>采购全过程项目管理（A21）、成立与换届选举（A23）、诉讼与法律事务（A24，暂缓）、违建违规处置（A25）。本轮不提供这些流程的操作按钮。</p></details></div>`}
 function home(){const pending=model.pending();return `<div class="home work-home"><div class="section-line"><span>继续办理</span><button class="link" data-page="tasks">全部待办 · ${pending.length}</button></div>${pending.slice(0,4).map(row).join('')||'<p class="a0-note">暂无进行中的事项。从下方输入事项，或从左侧选择业务。</p>'}<details class="work-deferred"><summary>建档后的资料准备</summary><div class="shortcuts"><button class="chip" data-module="A17">分配职责</button><button class="chip" data-module="A2" data-type="楼盘表">维护楼盘表</button><button class="chip" data-module="A3">录入物业合同</button><button class="chip" data-page="archive">查看小区档案</button></div></details><div class="home-input-area"><div class="home-composer">${composer(true)}</div><div class="shortcuts">${[['A4','筹备会议'],['A7','登记收支'],['A22','起草通知']].map(([id,t])=>`<button class="chip" data-work-new="${id}">${t}</button>`).join('')}</div></div></div>`}
 function row(r){const due=r.fields.due||r.fields.end||r.fields.date||'';return `<button class="row work-row" data-record="${r.id}"><span><strong>${h(r.title)}</strong><small>${h(r.number)} · ${h(catalog.find(m=>m.id===r.module)?.name)}${r.type?' / '+h(r.type):''}</small></span><span class="work-due ${due&&due<date()?'overdue':''}">${h(due||'无期限')}</span><span class="tag">${h(r.status)}</span>${icon('chevron')}</button>`}
 function tasks(){const all=model.pending();const visible=all.filter(r=>taskScope!=='mine'||r.fields.owner===person()?.id||r.createdBy===A0.phone()).filter(r=>!query||(r.title+r.number).includes(query));return `<div class="workspace work-page"><div class="page-head"><h1>我的待办</h1><span class="pill">${visible.length} 件</span></div><div class="work-toolbar"><div class="filters"><button data-task-scope="all" class="${taskScope==='all'?'active':''}">全部</button><button data-task-scope="mine" class="${taskScope==='mine'?'active':''}">与我有关</button></div><input id="work-search" placeholder="查找事项" value="${h(query)}" aria-label="查找事项"></div><p class="a0-note">点击事项回到来源模块办理；待办列表不会代替业务确认。</p>${visible.map(row).join('')||'<div class="blank">暂无待办</div>'}</div>`}
 function archiveRows(){const rows=model.read().records.filter(r=>['已归档','已定稿','已附证明'].includes(r.status)&&!(r.module==='A2'&&r.type==='楼盘表'));return rows.map(row).join('')||'<div class="blank">尚无业务归档件，完成业务后会在这里显示来源目录。</div>'}
 function library(){return `<div class="workspace work-page"><div class="page-head"><h1>资料库</h1><button class="secondary" data-module="A2">管理档案与三规</button></div><p class="a0-note">按来源查阅；原始材料保留在所属业务中。</p><button class="row" id="a0-archive-file"><span><strong>${h(c().file.name)}</strong><small>当届备案材料</small></span>${icon('chevron')}</button><h2>业务归档目录</h2>${archiveRows()}</div>`}
 function moneySummary(){const rs=model.read().records.filter(r=>r.module==='A7'&&r.type==='流水账'&&r.stage>0&&!['已作废','已撤回'].includes(r.status));const cents=r=>Math.round(Number(r.fields.amount)*100);const sum=kind=>rs.filter(r=>r.fields.direction===kind).reduce((n,r)=>n+cents(r),0);return `<div class="work-stats"><div>期初余额<strong>¥ ${(sum('期初余额')/100).toFixed(2)}</strong></div><div>收入<strong>¥ ${(sum('收入')/100).toFixed(2)}</strong></div><div>支出<strong>¥ ${(sum('支出')/100).toFixed(2)}</strong></div><div>账面结余<strong>¥ ${((sum('期初余额')+sum('收入')-sum('支出'))/100).toFixed(2)}</strong></div></div><p class="a0-note">以上按录入金额汇总，非银行余额；比例为核对信息，不自动拆分收支。</p>`}
 function moduleHTML(){const m=mod(),d=definition();if(selected){const r=get(selected);return r?detail(r):'<div class="blank">未找到记录</div>'}let list=records().filter(r=>(!query||(r.title+r.number).includes(query))&&(!status||r.status===status));return `<div class="workspace work-page"><div class="page-head"><div><span class="work-eyebrow">${h(m.group)}</span><h1>${h(m.name)}</h1></div><div class="work-buttons">${!d.readonly?'<button class="secondary" id="work-export">导出台账</button><button class="primary" id="work-new">新建</button>':''}</div></div><p class="a0-note">${h(m.hint)}</p>${m.tabs?`<div class="filters work-tabs">${m.tabs.map(t=>`<button data-work-tab="${h(t)}" class="${tab===t?'active':''}">${h(t)}</button>`).join('')}</div>`:''}${d.readonly?readonlyHTML():`${moduleId==='A7'?moneySummary()+'<button class="secondary" id="work-fund-report">按期间生成公示</button>':''}${moduleId==='A2'&&tab==='楼盘表'?roomTools():''}${moduleId==='A17'?rosterStrip():''}<div class="work-toolbar"><input id="work-search" aria-label="查找记录" placeholder="搜索标题或编号" value="${h(query)}"><select id="work-status" aria-label="筛选状态"><option value="">全部状态</option>${[...new Set(records().map(r=>r.status))].map(s=>`<option ${s===status?'selected':''}>${h(s)}</option>`).join('')}</select></div><div class="list">${list.map(row).join('')||'<div class="blank">暂无记录。新建后可逐步办理，也可在填写时载入示例。</div>'}</div>`}</div>`}
 function rosterStrip(){return `<details class="work-deferred"><summary>本届成员 · ${c().members.length} 人</summary><div class="a0-roster">${c().members.map(m=>`<div class="a0-roster-row"><strong>${h(m.name)}</strong><span>${h(m.role)}</span><span>${m.accountPhone?'已认领':'待认领'}</span></div>`).join('')}</div></details>`}
 function roomTools(){const rs=records().filter(r=>r.status==='已锁定');return `<div class="work-stats"><div>楼栋<strong>${new Set(rs.map(r=>r.fields.building)).size}</strong></div><div>单元<strong>${new Set(rs.map(r=>r.fields.building+'-'+r.fields.unit)).size}</strong></div><div>已锁定房屋<strong>${rs.length}</strong></div><div>已纳管记录<strong>${model.read().records.filter(r=>r.module==='A10'&&r.status==='已纳管').length}</strong></div></div><button class="secondary" id="work-rooms">批量录入房号</button>`}
 function readonlyHTML(){const data=model.read();if(moduleId==='A2')return archiveRows();if(moduleId==='A13')return `<form id="work-law"><label class="a0-field">描述你遇到的事情<textarea name="question" required placeholder="例如：物业合同到期，需要准备哪些材料？"></textarea></label><button class="primary">查询本地资料</button></form><div class="work-deferred"><h2>我的查询</h2>${data.queries.filter(q=>q.actor===A0.phone()).reverse().map(q=>`<div class="work-query"><p>${h(q.text)}</p><small>${h(q.result)} · 未生成法律结论</small><button class="link" data-query-delete="${q.id}">删除本条查询</button></div>`).join('')||'<p class="a0-note">暂无查询记录</p>'}</div>`;
 if(moduleId==='A19'){const counts={};data.queries.forEach(q=>counts[q.category]=(counts[q.category]||0)+1);return `<div class="list">${Object.entries(counts).map(([k,v])=>`<div class="row"><strong>${h(k)}</strong><span>${v} 次未命中</span></div>`).join('')||'<div class="blank">暂无未答问题汇总</div>'}</div>`}
 if(moduleId==='A20'){const plans=data.records.filter(r=>r.module==='A14'&&!['已作废','草稿'].includes(r.status)),actions=plans.flatMap(r=>r.checklist||[]),done=actions.filter(a=>a.done).length;return `<div class="work-stats"><div>计划动作完成率<strong>${actions.length?Math.round(done/actions.length*100)+'%':'—'}</strong><small>${done} / ${actions.length} 项</small></div><div>已召开委员会议<strong>${data.records.filter(r=>r.module==='A4'&&r.stage>=2&&r.status!=='已作废').length}</strong></div><div>已发布公示<strong>${data.records.filter(r=>r.module==='A11'&&r.stage>=2&&!['已撤回','已作废'].includes(r.status)).length}</strong></div></div><h2>居民满意度</h2><p class="a0-note">尚无居民评价数据。各维度及实名 / 匿名样本数待接入后展示，不生成虚构评分。</p><button class="secondary" data-work-new="A14">建立改进计划</button>`}
 return '<div class="blank">暂无居民评价汇总。未接入居民端，不展示虚构评分或评价人身份。</div>'}
 function display(f,value){if(value===undefined||value==='')return '未填写';if(f.type==='member')return memberName(value);if(['room','seal','meeting','property'].includes(f.type))return get(value)?.title||'来源不可用';if(f.type==='file')return (value||[]).map(v=>v.name).join('、');if(f.type==='check')return value?'已确认':'未确认';return String(value)}
 function detail(r){const d=model.def(r.module,r.type),s=d.steps?.[r.stage],fields=[...(d.fields||[]),...(d.steps||[]).flatMap(s=>s.fields||[])];const seen=new Set();return `<div class="workspace work-page"><button class="link" id="work-back">← ${h(d.name)}</button><div class="page-head"><div><span class="work-eyebrow">${h(r.number)} · ${h(r.type)}</span><h1>${h(r.title)}</h1></div><span class="pill">${h(r.status)}</span></div><div class="work-progress">${(d.steps||[]).map((s,i)=>`<span class="${i<r.stage?'done':i===r.stage?'current':''}">${i<r.stage?'✓':i+1} ${h(s.state)}</span>`).join('')}</div>${r.source?`<button class="link" data-record="${r.source}">查看来源事项</button>`:''}<dl class="a0-summary work-summary">${fields.filter(f=>{if(seen.has(f.key)||r.fields[f.key]===undefined)return false;seen.add(f.key);return true}).map(f=>`<dt>${h(f.label)}</dt><dd>${f.type==='file'?(r.fields[f.key]||[]).map((v,i)=>`<button class="link" data-file-key="${h(v.key)}">${h(v.name)}</button>`).join(' '):h(display(f,r.fields[f.key]))}</dd>`).join('')}</dl>${r.fields.inviteCode?`<div class="work-chat-card"><strong>演示邀请码：${h(r.fields.inviteCode)}</strong><p>有效期至 ${h(r.fields.expires)} · ${h(r.status)}。仅演示签发与撤销，未接居民端核销。</p></div>`:''}${r.checklist?`<section class="work-checklist"><h2>${r.module==='A12'?'十四类移交清单':'行动清单'}</h2>${r.checklist.map((x,i)=>`<button class="row" data-check-item="${i}"><span>${x.done?'☑':'□'} ${h(x.text)}${x.note?`<small>${h(x.note)}</small>`:''}</span></button>`).join('')}</section>`:''}<div class="work-buttons">${r.stage===0&&r.status!=='已作废'?'<button class="secondary" id="work-edit">修改草稿</button>':''}${s&&!['已作废','已撤回'].includes(r.status)?`<button class="primary" id="work-next">${h(s.label)}</button>`:''}<button class="secondary" id="work-supplement">补充材料</button>${r.stage>0&&!r.links?.length&&!['已归档','公示中','已附证明','已发文','已送达','已生效','已纳管','已入账','已结算','已作废','已撤回','已撤销','已锁定'].includes(r.status)?'<button class="secondary" id="work-return">退回草稿</button>':''}${r.module!=='A18'&&!['已作废','已撤回'].includes(r.status)?'<button class="link" id="work-cancel">撤回 / 作废</button>':''}</div>${r.module==='A4'?'<p class="a0-note">演示按本届正式委员过半出席检查；实际参数应以已核对的工作规则为准。</p>':''}${r.links?.length?`<section class="work-deferred"><h2>关联事项</h2>${r.links.map(id=>get(id)).filter(Boolean).map(row).join('')}</section>`:''}<details class="work-deferred"><summary>操作与材料记录 · ${r.history.length} 条</summary>${r.history.slice().reverse().map(e=>`<p class="a0-note">${h(e.action)} · ${h(new Date(e.at).toLocaleString())} · ${h(e.actor.slice(0,3)+'****'+e.actor.slice(7))}</p>`).join('')}${(r.supplements||[]).map(e=>`<p>${h(e.note||'补充附件')} ${(e.evidence||[]).map(v=>`<button class="link" data-file-key="${h(v.key)}">${h(v.name)}</button>`).join(' ')}</p>`).join('')}</details></div>`}
 function options(f){const rs=model.read().records;if(f.options)return f.options.map(s=>({value:s,label:s}));if(f.type==='member')return c().members.filter(m=>m.role!=='候补委员').map(m=>({value:m.id,label:m.name+' · '+m.role}));const matches={meeting:r=>r.module==='A4'&&['已定稿','已归档'].includes(r.status),room:r=>r.module==='A2'&&r.type==='楼盘表'&&r.status==='已锁定',seal:r=>r.module==='A18'&&r.type==='印章台账'&&r.status==='使用中',property:r=>r.module==='A3'&&['履行中','已评估'].includes(r.status)};return rs.filter(matches[f.type]||(()=>false)).map(r=>({value:r.id,label:r.title+' · '+r.number}))}
 function fieldHTML(f,v){const common=`name="${h(f.key)}" ${f.required?'required':''}`;const label=h(f.label)+(f.required?'':'（选填）');if(f.type==='check')return `<label class="a0-checkbox"><input type="checkbox" ${common} ${v?'checked':''}>${label}</label>`;
 if(['select','member','meeting','room','seal','property'].includes(f.type))return `<label class="a0-field">${label}<select ${common}><option value="">请选择</option>${options(f).map(o=>`<option value="${h(o.value)}" ${o.value===v?'selected':''}>${h(o.label)}</option>`).join('')}</select></label>`;
 if(f.type==='file')return `<label class="a0-field">${label}<input type="file" name="${h(f.key)}" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.csv,.txt,.jpg,.jpeg,.png,.webp"><small>${(v||[]).map(x=>h(x.name)).join('、')||'文件保存在本浏览器；每份不超过 20 MB'}</small></label>`;
 if(f.type==='textarea')return `<label class="a0-field">${label}<textarea ${common} rows="4">${h(v||'')}</textarea></label>`;
 return `<label class="a0-field">${label}<input ${common} type="${['money','percent','number'].includes(f.type)?'number':f.type}" ${['money','percent','number'].includes(f.type)?'min="0" step="'+(f.type==='number'?'1':'0.01')+'"':''} value="${h(v??'')}"></label>`}
 async function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('zhilin-business-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
 async function put(file){if(!file.size||file.size>20*1024*1024)throw Error('文件不能为空或超过 20 MB');const conn=await db(),key='wf-'+Date.now()+Math.random().toString(36).slice(2);await new Promise((resolve,reject)=>{const tx=conn.transaction('files','readwrite');tx.objectStore('files').put(file,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});conn.close();return {key,name:file.name,type:file.type}}
 async function previewFile(key){const all=model.read().records.flatMap(r=>[...Object.values(r.fields).filter(Array.isArray).flat(),...(r.supplements||[]).flatMap(s=>s.evidence||[])]);const meta=all.find(v=>v.key===key);if(meta?.demo){drawer(meta.name,`<div class="document-text">示例附件，仅用于体验流程。\n对应名称：${h(meta.name)}\n不是正式凭证，不代表实际签署、表决、付款或送达。</div>`);return}try{const conn=await db();const blob=await new Promise((resolve,reject)=>{const r=conn.transaction('files').objectStore('files').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});conn.close();if(!blob)throw Error('未找到本地文件');const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=meta?.name||'附件';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message)}}
 function sample(fields){const values={title:mod().name+' · 示例事项'};for(const f of fields){let v='示例：请根据实际资料核对';if(f.type==='file')v=[{key:'demo-'+Date.now()+f.key,name:'示例材料.txt',demo:true}];else if(['select','member','meeting','room','seal','property'].includes(f.type))v=options(f)[0]?.value||'';else if(f.type==='date')v=future();else if(f.type==='datetime-local')v=future(7)+'T14:00';else if(f.type==='check')v=true;else if(['number','money','percent'].includes(f.type))v=f.type==='percent'?'100':f.type==='money'?'100':'1';if(f.key==='title')v=mod().name+' · 示例事项';if(f.key==='actions')v='整理材料\n核对记录\n完成归档';if(f.key==='agenda')v='审议共有资金账目\n讨论停车管理事项';if(f.key==='body')v='本内容仅用于流程演示。请替换为经核对的正式内容。';if(f.key==='lastFour')v='0001';if(f.key==='building')v='1 栋';if(f.key==='unit')v='1 单元';if(f.key==='room')v='101';if(f.key==='version')v='v1.0';values[f.key]=v}return values}
 function editor(title,fields,values,save,button='保存',canSample=true){sampleValues=values;drawer(title,`<form id="work-form">${fields.map(f=>fieldHTML(f,values[f.key])).join('')}${errorHTML()}<p class="a0-note">当前为本地流程演示，不发送通知、不对外发布。</p><div class="work-buttons"><button class="primary" type="submit">${h(button)}</button>${canSample&&fields.length?'<button class="secondary" type="button" id="work-sample">载入示例</button>':''}</div></form>`);if($('#work-sample'))$('#work-sample').onclick=()=>editor(title,fields,{...values,...sample(fields)},save,button,canSample);$('#work-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{const data=new FormData(e.target),v={};for(const f of fields){if(f.type==='file'){const fs=data.getAll(f.key).filter(x=>x.size);v[f.key]=fs.length?await Promise.all(fs.map(put)):values[f.key]||[]}else v[f.key]=f.type==='check'?data.has(f.key):String(data.get(f.key)||'').trim()}await save(v);closeDrawer();render()}catch(e){error(e)}finally{b.disabled=false}}}
 function newRecord(id=moduleId){if(id!==moduleId||page!=='work'){location.assign(PageRoutes.url('work',{moduleId:id,action:'new'}));return;}const d=definition();editor('新建'+(tab||d.name),[{key:'title',label:'名称',type:'text',required:true},...(d.fields||[])],{},v=>{const r=model.add(moduleId,tab,v);selected=r.id},'保存草稿')}
 function next(){const r=get(selected),d=model.def(r.module,r.type),s=d.steps[r.stage];safe(()=>{model.allow(s.role,r);editor(s.label,s.fields||[],{},v=>model.next(r.id,v),'确认'+(s.label.includes('演示')?'（演示）':''))})}
 function exportRows(){const rows=model.exportLog(moduleId);download(mod().name+'台账.csv','\ufeff内部台账 · 不对外发布\n编号,名称,类型,状态\n'+rows.map(r=>[r.number,r.title,r.type,r.status].map(csv).join(',')).join('\n'),'text/csv')}
 const csv=s=>'"'+String(s??'').replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"';
 function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 function rooms(){editor('批量录入楼盘表',[{key:'lines',label:'每行填写：楼栋,单元,房号（不含面积）',type:'textarea',required:true}],{},v=>{const lines=v.lines.split('\n').filter(x=>x.trim()).map(x=>x.split(/[,，\t]/).map(s=>s.trim()));if(lines.some(x=>x.length!==3||x.some(y=>!y)))throw Error('每行须有楼栋、单元、房号三项');const existing=model.read().records.filter(r=>r.module==='A2'&&r.type==='楼盘表'&&r.status!=='已作废').map(r=>[r.fields.building,r.fields.unit,r.fields.room].join('|'));const all=[...existing,...lines.map(x=>x.join('|'))];if(new Set(all).size!==all.length)throw Error('存在重复房号，本次未导入，请核对');for(const [building,unit,room] of lines)model.add('A2','楼盘表',{title:building+' '+unit+' '+room,building,unit,room,propertyType:'住宅'});toast('已导入草稿，请逐项核对锁定')},'导入草稿',false)}
 function bind(){document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>navigate(b.dataset.module,b.dataset.type));document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>openRecord(b.dataset.record));document.querySelectorAll('[data-work-new]').forEach(b=>b.onclick=()=>newRecord(b.dataset.workNew));document.querySelectorAll('[data-work-tab]').forEach(b=>b.onclick=()=>navigate(moduleId,b.dataset.workTab));document.querySelectorAll('[data-file-key]').forEach(b=>b.onclick=()=>previewFile(b.dataset.fileKey));document.querySelectorAll('[data-task-scope]').forEach(b=>b.onclick=()=>{taskScope=b.dataset.taskScope;render()});
 if($('#work-search'))$('#work-search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#work-search').focus();$('#work-search').setSelectionRange(pos,pos)};
 if($('#work-module-search'))$('#work-module-search').oninput=e=>{const q=e.target.value;document.querySelectorAll('#work-directory [data-module]').forEach(b=>b.hidden=!b.textContent.includes(q));document.querySelectorAll('#work-directory section').forEach(s=>s.hidden=![...s.querySelectorAll('button')].some(b=>!b.hidden))};
 if($('#work-status'))$('#work-status').onchange=e=>{status=e.target.value;render()};if($('#work-new'))$('#work-new').onclick=()=>newRecord();if($('#work-back'))$('#work-back').onclick=()=>{selected='';render()};if($('#work-export'))$('#work-export').onclick=()=>safe(exportRows);if($('#work-next'))$('#work-next').onclick=next;
 if($('#work-edit'))$('#work-edit').onclick=()=>{const r=get(selected),d=definition();editor('修改草稿',[{key:'title',label:'名称',type:'text',required:true},...d.fields],r.fields,v=>model.edit(r.id,v))};
 if($('#work-supplement'))$('#work-supplement').onclick=()=>editor('补充材料',[{key:'note',label:'补充说明',type:'textarea',required:false},{key:'voucher',label:'补充凭证号',type:'text',required:false},{key:'evidence',label:'附件',type:'file',required:false}],{},v=>model.supplement(selected,v));
 if($('#work-return'))$('#work-return').onclick=()=>editor('退回草稿',[{key:'reason',label:'退回原因',type:'textarea',required:true}],{},v=>model.returnDraft(selected,v.reason),'确认退回',false);
 if($('#work-fund-report'))$('#work-fund-report').onclick=()=>editor('生成期间收支公示',[{key:'start',label:'开始日期',type:'date',required:true},{key:'end',label:'结束日期',type:'date',required:true},{key:'meetingId',label:'审议共有资金的会议',type:'meeting',required:true}],{},v=>{const r=model.report(v);moduleId='A11';tab='';selected=r.id},'生成草稿',false);
 if($('#work-cancel'))$('#work-cancel').onclick=()=>editor('撤回 / 作废记录',[{key:'reason',label:'原因（原记录保留）',type:'textarea',required:true}],{},v=>model.cancel(selected,v.reason),'确认记录',false);
 document.querySelectorAll('[data-check-item]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.checkItem),x=get(selected).checklist[i];editor(x.done?'重新打开清单项':'完成清单项',[{key:'note',label:'办理说明 / 移交记录',type:'textarea',required:true}],{},v=>model.tick(selected,i,!x.done,v.note),'保存记录',false)});
 if($('#work-law'))$('#work-law').onsubmit=e=>{e.preventDefault();safe(()=>{model.query(new FormData(e.target).get('question'));render()})};document.querySelectorAll('[data-query-delete]').forEach(b=>b.onclick=()=>{model.removeQuery(b.dataset.queryDelete);render()});if($('#work-rooms'))$('#work-rooms').onclick=rooms;
 }
 const keywords=[['A6',/业主大会/],['A4',/会议|开会|纪要/],['A5',/议案|提议/],['A7',/收支|收益|记账|预算|资金/],['A15',/对外合同|采购合同|经营合同|验收|质保/],['A3',/物业合同|服务标准|物业公司|合同/],['A8',/监督|整改|调查|服务报告|评价/],['A9',/纠纷|调解|噪音|漏水/],['A10',/居民|纳管|房屋认领/],['A11',/公示|公告/],['A22',/通知|函件|发函|发文/],['A18',/印章|用印|盖章/],['A14',/计划|行动|改进/],['A16',/志愿者|排班/],['A12',/换届|交接/],['A17',/分工|职责|委员变动/],['A2',/档案|三规|楼盘|房号|资料/],['A13',/法规|法律|条例|依据/],['A19',/未答|盲区/],['A20',/履职|满意度/]];
 function respond(s,text){if(/待办|今日|今天.*事/.test(text)){s.messages.push({role:'assistant',text:`当前有 ${model.pending().length} 件进行中的事项。进入待办列表可继续办理。`,workAction:'tasks'});return}const hit=keywords.find(([id,re])=>re.test(text));if(hit){const m=catalog.find(m=>m.id===hit[0]);s.messages.push({role:'assistant',text:`可以从「${m.name}」继续。${m.hint}`,workModule:m.id});s.title=m.name+' · '+text.slice(0,12)}else s.messages.push({role:'assistant',text:'请告诉我要办理的事项，例如“筹备委员会议”“登记公共收益”或“起草通知”。当前按关键词引导办理，尚未接入真实 AI。',workAction:'business'})}
 function chatCard(m){return m.workModule?`<div class="work-chat-card"><strong>${h(catalog.find(x=>x.id===m.workModule).name)}</strong><div class="work-buttons"><button class="primary" data-module="${m.workModule}">查看与办理</button>${!catalog.find(x=>x.id===m.workModule).readonly?`<button class="secondary" data-work-new="${m.workModule}">新建事项</button>`:''}</div></div>`:m.workAction?`<button class="secondary" data-page="${m.workAction}">${m.workAction==='tasks'?'打开待办':'浏览小区事务'}</button>`:''}
 function restore(id,params){if(!catalog.some(m=>m.id===id))return;moduleId=id;const m=mod();tab=m.tabs?.includes(params.get('type'))?params.get('type'):m.tabs?.[0]||'';selected=params.get('record')||'';}
 return {restore,newRecord,state:()=>({moduleId,tab,selected}),library,directory,home,tasks,moduleHTML,bind,respond,chatCard,navigate,model,title:()=>mod()?.name||'小区事务'};
})();
